                xml_write(xmlOut, xmlOut_size, &xmlOut_pos, "<{http://www.w3.org/2000/09/xmldsig#}SPKIData>", 46);
                error = decode_iso2_SPKIDataType(stream, &xmldsigFrag->SPKIData, xmlOut, xmlOut_size, &xmlOut_pos);
